/**
 * PrintLatch browser client — communicates with the locally-installed
 * PrintLatch agent on the shopkeeper's Windows machine.
 *
 * ARCHITECTURE:
 *   1. The shopkeeper's browser (on the same Windows machine as PrintLatch)
 *      sends HTTP requests to http://127.0.0.1:32191 (the agent's port).
 *   2. The PrintLatch agent verifies the Origin header matches a paired
 *      origin (the shopkeeper runs `printlatch pair --origin <url>` to pair
 *      the PrintShop origin).
 *   3. The browser fetches the order's PDF from a short-lived presigned URL
 *      (generated by the authenticated server) + sends the bytes to the
 *      local agent for printing.
 *
 * SECURITY:
 *   - The presigned PDF URL is short-lived (60s) + object-specific.
 *   - The PrintLatch agent only accepts requests from paired origins.
 *   - No server secrets, pairing tokens, or local-agent credentials are
 *     in the browser bundle.
 *   - The server's `withAuth(['owner'])` + `repos.shops.getByOwner` enforce
 *     that only the shop's owner can request a print URL.
 *   - The customer's tracking token is NOT used for print authorization.
 */

const AGENT_BASE_URL = 'http://127.0.0.1:32191';
const AGENT_STATUS_PATH = '/api/status';
const AGENT_JOBS_PATH = '/api/jobs';
const AGENT_JOB_PATH = '/api/jobs';
const AGENT_PAIR_PATH = '/api/pair';

export type PrintLatchConnectionState =
  | 'not-configured'
  | 'pairing-required'
  | 'connected'
  | 'disconnected'
  | 'error';

export interface PrintLatchStatus {
  connected: boolean;
  paired: boolean;
  origin?: string;
  printers?: string[];
  version?: string;
}

export interface PrintLatchJobRequest {
  pdf: Uint8Array;
  filename: string;
  copies: number;
  colorMode: 'bw' | 'color';
  duplex: boolean;
  paperSize: string;
  pageRange?: string;
  printer?: string;
}

export interface PrintLatchJobResponse {
  id: string;
  status: 'queued' | 'submitting' | 'accepted' | 'completed' | 'failed' | 'unknown';
  error?: string;
}

export interface PrintLatchJobStatus {
  id: string;
  status: 'queued' | 'submitting' | 'accepted' | 'completed' | 'failed' | 'unknown';
  error?: string;
  printer?: string;
  submittedAt?: string;
  completedAt?: string;
}

export async function checkPrintLatchStatus(): Promise<{ state: PrintLatchConnectionState; status: PrintLatchStatus | null; error: string | null }> {
  try {
    const res = await fetch(`${AGENT_BASE_URL}${AGENT_STATUS_PATH}`, {
      method: 'GET',
      headers: { 'Content-Type': 'application/json' },
      signal: AbortSignal.timeout(5000),
    });
    if (!res.ok) {
      return { state: 'error', status: null, error: `Agent responded HTTP ${res.status}` };
    }
    const data = (await res.json()) as PrintLatchStatus;
    if (!data.connected) return { state: 'disconnected', status: data, error: null };
    if (!data.paired) return { state: 'pairing-required', status: data, error: null };
    return { state: 'connected', status: data, error: null };
  } catch (e: any) {
    if (e.name === 'TimeoutError' || e.name === 'AbortError') {
      return { state: 'disconnected', status: null, error: 'Agent did not respond (5s timeout). Is PrintLatch running on THIS computer? (127.0.0.1 only works if your browser and PrintLatch are on the same machine.)' };
    }
    if (e.name === 'TypeError' && /fetch|Failed/i.test(e.message)) {
      return { state: 'disconnected', status: null, error: 'Agent not reachable. Common causes: (1) PrintLatch is not running — open http://127.0.0.1:32191/app/ to check. (2) You are on a different computer than PrintLatch — the agent only works on the SAME Windows machine as your browser. (3) Run the pairing command first (Step 2 on the Printer Setup page) — the agent only accepts browser requests after pairing.' };
    }
    return { state: 'error', status: null, error: e.message ?? 'Unknown error' };
  }
}

export async function submitPrintLatchJob(req: PrintLatchJobRequest): Promise<PrintLatchJobResponse> {
  const formData = new FormData();
  const blob = new Blob([req.pdf as unknown as BlobPart], { type: 'application/pdf' });
  formData.append('pdf', blob, req.filename);
  formData.append('copies', String(req.copies));
  formData.append('colorMode', req.colorMode);
  formData.append('duplex', String(req.duplex));
  formData.append('paperSize', req.paperSize);
  if (req.pageRange) formData.append('pageRange', req.pageRange);
  if (req.printer) formData.append('printer', req.printer);

  const res = await fetch(`${AGENT_BASE_URL}${AGENT_JOBS_PATH}`, {
    method: 'POST',
    body: formData,
    signal: AbortSignal.timeout(30000),
  });
  if (!res.ok) {
    const errorText = await res.text().catch(() => '');
    throw new Error(`PrintLatch job submission failed (HTTP ${res.status}): ${errorText || 'unknown error'}`);
  }
  return (await res.json()) as PrintLatchJobResponse;
}

export async function getPrintLatchJobStatus(jobId: string): Promise<PrintLatchJobStatus> {
  const res = await fetch(`${AGENT_BASE_URL}${AGENT_JOB_PATH}/${jobId}`, {
    method: 'GET',
    headers: { 'Content-Type': 'application/json' },
    signal: AbortSignal.timeout(5000),
  });
  if (!res.ok) {
    if (res.status === 404) {
      return { id: jobId, status: 'unknown', error: 'Job not found — may have been completed or lost.' };
    }
    throw new Error(`PrintLatch status check failed (HTTP ${res.status})`);
  }
  return (await res.json()) as PrintLatchJobStatus;
}

export async function fetchPdfBytes(presignedUrl: string): Promise<Uint8Array> {
  const res = await fetch(presignedUrl, { signal: AbortSignal.timeout(30000) });
  if (!res.ok) throw new Error(`Failed to fetch PDF (HTTP ${res.status})`);
  const buf = await res.arrayBuffer();
  return new Uint8Array(buf);
}

export const PRINTLATCH_AGENT_URL = AGENT_BASE_URL;
export const PRINTLATCH_DASHBOARD_URL = `${AGENT_BASE_URL}/app/`;

export function getPairingCommand(): string {
  const origin = typeof window !== 'undefined' ? window.location.origin : 'https://your-printshop.vercel.app';
  // PowerShell requires the call operator (&) to invoke a quoted path, and
  // uses $env: prefix for environment variables (NOT %VAR% which is CMD-only).
  // Without &, PowerShell treats "%LOCALAPPDATA%\..." as a string literal
  // and throws "Unexpected token 'pair'".
  return `& "$env:LOCALAPPDATA\\PrintLatch\\bin\\printlatch.exe" pair --origin ${origin} --name "PrintShop SaaS"`;
}

export const PRINTLATCH_EXE_PATH = '%LOCALAPPDATA%\\PrintLatch\\bin\\printlatch.exe';

/**
 * Confirm the PrintLatch pairing by sending the pairing code (generated by
 * the `printlatch pair` command) to the local agent. The agent verifies:
 *   1. The code matches a pending pairing request.
 *   2. The request's Origin header matches the origin specified in the
 *      `printlatch pair --origin <url>` command.
 * If both match, the agent records the origin as paired + future requests
 * from this origin are accepted.
 *
 * RETURNS: { success: boolean; error?: string }
 */
export async function confirmPrintLatchPairing(pairingCode: string): Promise<{ success: boolean; error?: string }> {
  try {
    const res = await fetch(`${AGENT_BASE_URL}${AGENT_PAIR_PATH}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ code: pairingCode }),
      signal: AbortSignal.timeout(5000),
    });
    if (!res.ok) {
      const errorText = await res.text().catch(() => '');
      return { success: false, error: `Pairing confirmation failed (HTTP ${res.status}): ${errorText}` };
    }
    const data = await res.json();
    return { success: true, error: data?.error };
  } catch (e: any) {
    if (e.name === 'TypeError' && /fetch|Failed/i.test(e.message)) {
      return { success: false, error: 'Agent not reachable. Is PrintLatch running? Run the pairing command first, then click Confirm.' };
    }
    return { success: false, error: e.message ?? 'Unknown error during pairing confirmation' };
  }
}
